package br.com.fastfps.render; public final class DynamicBudget{private long last=System.nanoTime();private float ms=16.67f;private int uploads,bytes;public void tick(){long n=System.nanoTime();ms=(n-last)/1000000f;last=n;uploads=bytes=0;}public float frameTimeMillis(){return ms;}public boolean allowUpload(int size,int maxUploads,int maxBytes){if(uploads>=maxUploads||bytes+size>maxBytes)return false;uploads++;bytes+=size;return true;}public boolean overloaded(float limit){return ms>limit;}}
